            "parent_gender": 3396,
            "keywords": [2106, 821, 2566, 1106],
            "meta_keywords": "fathers, dad, dads, father, preterm birth, premature birth, premmies, premature babies, premature baby",
            "related_articles": [2811, 2826, 2816, 2831, 2821, 2841],
            "related_video_articles": [1791, 2251],
