            "child_gender": 716,
            "parent_gender": 3396,
            "keywords": [2826, 1591, 2226, 791],
            "meta_keywords": "blood glucose, glucose, sugar levels, blood sugar levels, blood sugar, low Glycaemic Index, glycemic food index, low carbohydrates diet, carbohydrate foods, carbs, carbohydrates",
