            "cover_image": {
                "url": "https://rerai.umntwana.app/sites/zimbabwe/files/styles/content_1200xh_/public/2025-09/healthy-relationships-with-partners-in-pregnancy.webp?itok=TpR_qMjJ",
                "name": "Healthy relationships with partners in pregnancy.png",
                "alt": "Healthy relationships with partners in pregnancy"
            }
