            "parent_gender": 3396,
            "keywords": [2201, 1126, 1671, 1066, 2896, 1541],
            "meta_keywords": "hurukuro, kunonoka kwemutauro, kutaurirana, unyanzvi hwemutauro, kukura kwemutauro, tamba",
            "related_articles": [1861, 2146, 2201, 2151, 1866, 1841, 1851, 1846, 2161, 2166],
