            "meta_keywords": "zviito zvemazuva ose, kukura kwevacheche",
            "related_articles": [2291, 1826, 1816, 2146],
            "related_video_articles": [1791, 2241, 2301],
            "premature": 0,
            "do_not_feature": "0",
            "embedded_images": [],
