            "cover_image": {
                "url": "https://rerai.umntwana.app/sites/zimbabwe/files/styles/content_1200xh_/public/2026-02/gassy-baby.webp?itok=7ktSdxWX",
                "name": "gassy-baby.jpeg",
                "alt": "Gassy baby"
            }
