            "child_gender": 716,
            "parent_gender": 3396,
            "keywords": [2696, 1961],
            "meta_keywords": "kushungurudzika kwepamuviri, PND, baby blues, post-natal depression, post-natal depression",
            "related_articles": [2776, 2801, 2796, 2791, 2671],
            "related_video_articles": [2251, 1791, 2511, 2241],
